from itertools import combinations

from rules import allowed


def solve(data):
    k = data["k"]
    blocked = set(data.get("blocked", []))
    options = [job for job in data["jobs"] if job["id"] not in blocked]

    best = None
    best_value = None
    for choice in combinations(options, k):
        if not allowed(choice, data):
            continue
        ids = sorted(job["id"] for job in choice)
        value = sum(job["value"] for job in choice)
        if (best is None or value > best_value
                or (value == best_value and ids < best)):
            best = ids
            best_value = value

    if best is None:
        return {"error": "impossible"}
    return {"selected": best, "value": best_value}

from collections import Counter

POLICY = {"capacity": 2, "tie": "smallest"}


def allowed(selected, data):
    jobs = list(selected)
    ids = {job["id"] for job in jobs}
    if not set(data.get("mandatory", [])).issubset(ids):
        return False

    counts = Counter(job["group"] for job in jobs)
    for group, bounds in data.get("quotas", {}).items():
        low, high = bounds
        if not low <= counts[group] <= high:
            return False

    active_ends = []
    for job in sorted(jobs, key=lambda row: (row["start"], row["end"])):
        start = job["start"]
        active_ends = [end for end in active_ends if end > start]
        active_ends.append(job["end"])
        if len(active_ends) > POLICY["capacity"]:
            return False
    return True

import heapq
from rules import departures, visit_mask


def solve(data):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = visit_mask(source, required)
    initial = (source, initial_mask, data["coupons"])
    distance = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distance.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}

        for edge in graph[node]:
            for next_time, next_remaining in departures(edge, arrival, remaining):
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | visit_mask(next_node, required)
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distance.get(next_state, float("inf")):
                    distance[next_state] = next_time
                    heapq.heappush(
                        queue,
                        (next_time, next_node, next_mask, next_remaining),
                    )

    return {"arrival": None}

POLICY = {"coupon_rule": "at_most", "minimum_duration": 1}


def departures(edge, arrival, coupons_left):
    depart = max(arrival, edge["open"])
    # The closing time limits departure and is therefore exclusive.
    if depart >= edge["close"]:
        return []

    choices = [(depart + edge["duration"], coupons_left)]
    if coupons_left > 0:
        duration = max(
            POLICY["minimum_duration"],
            edge["duration"] - edge.get("discount", 0),
        )
        choices.append((depart + duration, coupons_left - 1))
    return choices


def visit_mask(node, required):
    mask = 0
    for index, name in enumerate(required):
        if node == name:
            mask |= 1 << index
    return mask

