from rules import POLICY, active_dependencies, acyclic


def solve(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    # A candidate is either absent or one of the package's permitted versions.
    choices = []
    for name in names:
        versions = sorted(
            row["version"] for row in packages[name]
            if row["version"] not in blocked.get(name, [])
            and (name not in pins or row["version"] == pins[name])
        )
        choices.append(versions[::-1] + [None])

    def valid(selection):
        for name, bounds in roots.items():
            version = selection.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                return False

        rows_by_name = {
            name: {row["version"]: row for row in packages[name]}
            for name, version in selection.items() if version is not None
        }
        edges = {}
        for name, version in selection.items():
            if version is None:
                continue
            row = rows_by_name[name][version]
            deps = active_dependencies(row, features)
            edges[name] = []
            for dep in deps:
                target = selection.get(dep["name"])
                if target is None or not dep["min"] <= target <= dep["max"]:
                    return False
                edges[name].append(dep["name"])

        if not acyclic(edges):
            return False

        reachable = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            pending.extend(edges.get(name, []))
        return reachable == {name for name, version in selection.items()
                             if version is not None}

    # Names are already in descending order; descending versions precede absence,
    # so the first feasible complete assignment is the required lexicographic max.
    for values in product(*choices):
        selection = dict(zip(names, values))
        if valid(selection):
            return {"versions": {name: version for name, version in selection.items()
                                  if version is not None}}
    return {"error": "unsatisfiable"}

