    if POLICY["revision_priority"] == "sequence_first":
        return (event.get("sequence", 0), event.get("revision", 0), position)
    return (event.get("revision", 0), position)


def amount(event, mode):
    raw = event["price"] * event.get("quantity", 1)
    discount = min(10000, max(0, event.get("discount_bp", 0)))
    net = rounded(raw * (10000 - discount), 10000, mode)

    base = net if POLICY["tax_base"] == "discounted" else raw
    tax = rounded(base * event.get("tax_bp", 0), 10000, mode)
    total = net + tax
    return -total if event.get("kind") == "refund" else total

import heapq
from rules import departures, visit_mask


def solve(data):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    source = data["source"]
    target = data["target"]
    start = data["start"]
    deadline = data["deadline"]

    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    initial_mask = visit_mask(source, required)
    initial_state = (source, initial_mask, data["coupons"])
    distance = {initial_state: start}
    queue = [(start, source, initial_mask, data["coupons"])]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distance.get(state) != arrival:
            continue
        if node == target and mask == full:
            return {"arrival": arrival}

        for edge in graph[node]:
            for next_time, next_remaining in departures(edge, arrival, remaining):
                if next_time > deadline:
                    continue
                next_node = edge["v"]
                next_mask = mask | visit_mask(next_node, required)
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distance.get(next_state, float("inf")):
                    distance[next_state] = next_time
                    heapq.heappush(
                        queue, (next_time, next_node, next_mask, next_remaining)
                    )

    return {"arrival": None}

POLICY = {"coupon_rule": "at_most", "minimum_duration": 2}


def departures(edge, arrival, coupons_left):
    depart = max(arrival, edge["open"])
    if depart >= edge["close"]:
        return []

    duration = edge["duration"]
    choices = [(depart + duration, coupons_left)]
    if coupons_left > 0:
        discounted_duration = max(
            POLICY["minimum_duration"], duration - edge.get("discount", 0)
        )
        choices.append((depart + discounted_duration, coupons_left - 1))
    return choices


def visit_mask(node, required):
    mask = 0
    for index, name in enumerate(required):
        if node == name:
            mask |= 1 << index
    return mask

from itertools import combinations

from rules import allowed


def solve(data):
    blocked = set(data.get("blocked", []))
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    k = data["k"]

    best_value = None
    best_ids = None
    for choice in combinations(jobs, k):
        if not allowed(choice, data):
            continue
        ids = tuple(sorted(job["id"] for job in choice))
        value = sum(job["value"] for job in choice)
        if (best_value is None or value > best_value
                or (value == best_value and ids > best_ids)):
            best_value = value
            best_ids = ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}

import heapq
from collections import Counter

POLICY = {"capacity": 2, "tie": "largest"}


def allowed(selected, data):
    ids = {job["id"] for job in selected}
    if not set(data.get("mandatory", [])).issubset(ids):
        return False

    counts = Counter(job["group"] for job in selected)
    for group, (low, high) in data.get("quotas", {}).items():
        if not low <= counts.get(group, 0) <= high:
            return False

    active_ends = []
    for job in sorted(selected, key=lambda row: (row["start"], row["end"], row["id"])):
        while active_ends and active_ends[0] <= job["start"]:
            heapq.heappop(active_ends)
        heapq.heappush(active_ends, job["end"])
        if len(active_ends) > POLICY["capacity"]:
            return False
    return True

from itertools import product

from rules import active_dependencies, acyclic


def solve(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    # Each package may be absent or installed at one of its available versions.
    choices = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name])
        choices.append([-1] + versions)

    best_vector = None
    best_versions = None

    for assignment in product(*choices):
        selected = dict(zip(names, assignment))
        installed = {name: version for name, version in selected.items() if version != -1}

        # Roots must be installed within their requested ranges.
        if any(name not in installed or not bounds[0] <= installed[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        # Pins and blocks constrain installed packages, but do not install packages.
        if any(version in blocked.get(name, []) or
               (name in pins and pins[name] != version)
               for name, version in installed.items()):
            continue

        rows_by_version = {
            name: {row["version"]: row for row in packages[name]}
            for name in installed
        }
        edges = {name: [] for name in installed}
        valid = True
        for name, version in installed.items():
            row = rows_by_version[name][version]
            for dep in active_dependencies(row, features):
                target = dep["name"]
                target_version = installed.get(target)
                if target_version is None or not dep["min"] <= target_version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid or not acyclic(edges):
            continue

        # The installation must be exactly the dependency closure of the roots.
        reachable = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            pending.extend(edges[name])
        if reachable != set(installed):
            continue

        vector = tuple(selected[name] for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_versions = installed

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

POLICY = {"preference": "maximum", "name_order": "ascending"}


def active_dependencies(row, features):
    return [dependency for dependency in row.get("deps", [])
            if not dependency.get("feature") or dependency["feature"] in features]


def acyclic(edges):
    finished = set()
    active = set()

    def visit(name):
        if name in active:
            return False
        if name in finished:
            return True
        active.add(name)
        for other in edges.get(name, []):
            if not visit(other):
                return False
        active.remove(name)
        finished.add(name)
        return True

    return all(visit(name) for name in edges)
